import{j as o,r as s}from"./index-D8QrJLTG.js";import{useMode as n}from"./ModeContext-D2Y9a8rF.js";const i={fr:{overlay_tagline:"Au croisement de la science, du son et du storytelling.",overlay_cta:"Vivre l'expérience sonore",intro_eyebrow:"Rendre le son vivant.",intro_start:"Lancer l'expérience sonore",intro_scroll:"Scrollez pour explorer",s0_title:"Un lieu a une âme.",s1_title:"Elle s'entend.",s2_title:"Chaque zone a son propre rôle",s3_title:"Elle se ressent.",s4_title:"Elle vit avec vous.",s5_title:"Et grandit avec vous.",s0_p1:"« La musique, c'est 50% d'un film. » Francis Ford Coppola.",s0_p2:"Dans nos boutiques et nos événements pourtant, cette magie disparaît. Le son y est subi : une playlist en boucle, aveugle à qui est là, à ce qu'ils ressentent, à l'histoire qu'on voudrait raconter.",s0_p3:"Au cinéma, la musique désigne le personnage principal : elle le suit, réagit à ses émotions, l'élève. Nous faisons la même chose, mais pour vos visiteurs.",s1_p1:"Un salon bondé, une boutique un vendredi soir : le brouhaha s'accumule, fatigue, et pousse doucement vers la sortie.",s1_p2:"Au cinéma, le réalisateur sait isoler un personnage dans le chaos. Le monde s'efface, et il ne reste qu'une bulle d'intimité, le temps d'une scène.",s1_p3:"Nous faisons exactement cela dans le monde physique. Une bulle de clarté, invisible, au milieu du vacarme.",s2_p1:"Un visiteur n'est pas dans le même état d'esprit à l'entrée, devant un rayon, ou dans un espace dédié aux équipes.",s2_p2:"Le son peut accompagner chacun de ces moments, pour les visiteurs comme pour les collaborateurs, sans que personne ne le remarque consciemment.",s2_p3:"Trois intentions sonores. Un seul système. Pour l'expérience client comme pour le bien-être des équipes.",s3_p1:"Un simple changement d'accord transforme une scène de joie en nostalgie. La musique modifie notre rythme cardiaque, notre respiration, souvent avant même qu'on s'en rende compte.",s3_p2:"Près de 80% de la recherche sur les effets du son sur le cerveau a été publiée ces dix dernières années. Nous pouvons désormais l'utiliser avec une précision inédite.",s3_p3:"Concentration, apaisement, énergie : nous pouvons aujourd'hui composer l'état émotionnel d'un lieu comme un réalisateur compose sa bande originale.",s4_p1:"La musique ne joue plus pour remplir le silence. Grâce aux travaux de notre équipe en neurosciences, elle active en temps réel des paramètres émotionnels et comportementaux précis, propres à chaque moment, chaque intention, chaque client.",s4_p2:"Pour en faire l'expérience : activez votre caméra. Souriez, ou non. La musique vous lira.",s4_p3:"C'est ce que chacun de vos visiteurs peut vivre, sans le savoir, simplement en étant là.",s5_p1:"Imaginez une pièce avec un simple drone sonore. Une personne entre et un violon s'éveille. Une deuxième s'approche et un rythme apparaît, doucement.",s5_p2:"La musique ne remplit plus l'espace : elle lui répond. Plus riche, plus dense, au rythme de ceux qui arrivent.",s5_p3:"Elle attire ceux qui passent. Elle accueille ceux qui entrent, et récompense ceux qui restent.",scroll_prompt:"Continuez de scroller",isolation_on:"Isolation activée",isolation_off:"Bruit ambiant",density_label:"couches sonores",zone_entree:"Entrée",zone_entree_sub:"Créer l'envie de rester",zone_rayon:"Rayon",zone_rayon_sub:"Stimuler l'exploration",zone_equipe:"Espace équipe",zone_equipe_sub:"Soutenir le bien-être",neuro_relaxation:"Relaxation",neuro_regulation:"Régulation émotionnelle",neuro_focus:"Focus cognitif",webcam_active:"Caméra active",webcam_authorize:"Autoriser la caméra",webcam_reading:"Lecture du geste",webcam_hint:"Autorisez la caméra, placez-vous face à elle en pleine lumière, puis bougez lentement. La musique réagit à votre présence et à votre mouvement.",webcam_move_hint:"Bougez devant la caméra : la barre suit votre mouvement.",webcam_denied:"Caméra bloquée. Autorisez l'accès dans les réglages du navigateur, puis réessayez.",webcam_unavailable:"Caméra indisponible. Vérifiez qu'aucune autre application ne l'utilise, puis réessayez.",footer_about:"Qui sommes-nous",footer_legal:"Mentions légales",footer_contact:"Nous contacter",footer_email_placeholder:"Votre email",footer_message_placeholder:"Votre message",footer_send:"Envoyer",footer_copyright:"© 2026 Kikina Lab. Tous droits réservés.",footer_mailto_subject:"Contact depuis Kikiscroll",footer_mailto_body_prefix:"De : ",legal_title:"Mentions Légales",legal_editor:"Éditeur du site :",legal_editor_value:"Kikina Lab / Kikina Studio",legal_address_label:"Siège social :",legal_address_value:"Paris, France",legal_contact_label:"Contact :",legal_hosting_label:"Hébergement :",legal_hosting_value:"Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723",legal_privacy:"Ce site utilise une détection de mouvement par caméra implémentée en JavaScript natif (différence d'images sur canvas). Aucune donnée d'image n'est enregistrée ou transmise à des serveurs tiers ; l'analyse est effectuée localement dans votre navigateur en temps réel.",legal_close:"Fermer"},en:{overlay_tagline:"At the crossroads of science, sound, and storytelling.",overlay_cta:"Start the sound experience",intro_eyebrow:"Making sound come alive.",intro_start:"Start the sound experience",intro_scroll:"Scroll to explore",s0_title:"A place has a soul.",s1_title:"It can be heard.",s2_title:"Each zone has its own role",s3_title:"It can be felt.",s4_title:"It lives with you.",s5_title:"And grows with you.",s0_p1:"“Music is 50% of a film.” Francis Ford Coppola.",s0_p2:"Yet in our stores and events, this magic disappears. Sound is an afterthought: a playlist on loop, oblivious to who is there, what they feel, or the story waiting to be told.",s0_p3:"In cinema, music singles out the main character: it follows them, reacts to their emotions, elevates them. We do the same, for your visitors.",s1_p1:"A crowded salon, a boutique on a Friday evening: noise accumulates, fatigues, and quietly drives guests toward the door.",s1_p2:"In cinema, the director knows how to isolate a character in the chaos. The world fades away, leaving only a bubble of intimacy for the length of a scene.",s1_p3:"We do exactly that in the physical world. A bubble of clarity, invisible, in the middle of the din.",s2_p1:"A visitor is not in the same frame of mind at the entrance, before a display, or in a space reserved for the team.",s2_p2:"Sound can accompany each of these moments, for visitors and staff alike, without anyone consciously noticing.",s2_p3:"Three sonic intentions. One system. For the guest experience and for team well-being.",s3_p1:"A simple chord change turns a scene of joy into nostalgia. Music alters our heart rate, our breathing, often before we even realise.",s3_p2:"Nearly 80% of research on the effects of sound on the brain has been published in the last ten years. We can now use it with unprecedented precision.",s3_p3:"Focus, calm, energy. Today we can compose the emotional state of a place the way a director composes a film score.",s4_p1:"Music no longer plays to fill silence. Informed by our neuroscience team's research, it activates precise emotional and behavioural parameters in real time, tailored to each moment, each intention, each guest.",s4_p2:"To experience it: turn on your camera. Smile, or don't. The music will read you.",s4_p3:"This is what each of your visitors can experience, without knowing it, simply by being there.",s5_p1:"Imagine a room with a simple sonic drone. Someone walks in and a violin awakens. A second person approaches and a rhythm emerges, softly.",s5_p2:"Music no longer fills the space. It responds to it. Richer, denser, in step with those who arrive.",s5_p3:"It intrigues those who pass. It welcomes those who enter. It rewards those who stay.",scroll_prompt:"Keep scrolling",isolation_on:"Isolation active",isolation_off:"Ambient noise",density_label:"sound layers",zone_entree:"Entrance",zone_entree_sub:"Inspire the desire to linger",zone_rayon:"Display",zone_rayon_sub:"Inspire exploration",zone_equipe:"Team space",zone_equipe_sub:"Support well-being",neuro_relaxation:"Relaxation",neuro_regulation:"Emotional regulation",neuro_focus:"Cognitive focus",webcam_active:"Camera active",webcam_authorize:"Allow camera",webcam_reading:"Reading the gesture",webcam_hint:"Allow the camera, face it in good light, then move slowly. The music responds to your presence and your movement.",webcam_move_hint:"Move in front of the camera — the bar follows your movement.",webcam_denied:"Camera blocked. Allow access in your browser settings, then try again.",webcam_unavailable:"Camera unavailable. Make sure no other app is using it, then try again.",footer_about:"About us",footer_legal:"Legal notice",footer_contact:"Contact us",footer_email_placeholder:"Your email",footer_message_placeholder:"Your message",footer_send:"Send",footer_copyright:"© 2026 Kikina Lab. All rights reserved.",footer_mailto_subject:"Contact from Kikiscroll",footer_mailto_body_prefix:"From: ",legal_title:"Legal Notice",legal_editor:"Site publisher:",legal_editor_value:"Kikina Lab / Kikina Studio",legal_address_label:"Registered office:",legal_address_value:"Paris, France",legal_contact_label:"Contact:",legal_hosting_label:"Hosting:",legal_hosting_value:"Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723",legal_privacy:"This site uses webcam motion detection implemented in pure JavaScript (frame-difference on a canvas). No image data is recorded or transmitted to third-party servers; analysis is performed locally in your browser in real time.",legal_close:"Close"}},r={fr:{overlay_tagline:"Au croisement de la science, du son et du soin.",overlay_cta:"Entrer dans l'expérience sonore",intro_eyebrow:"Composer la présence.",intro_start:"Lancer l'expérience sonore",intro_scroll:"Faites défiler lentement pour explorer",intro_line_1:"Ceci n'est pas un site web.",intro_line_2:"C'est une expérience d'une minute.",intro_line_3:"Faites défiler lentement. Son activé.",s0_title:"Le son, signature du soin.",s1_title:"La science de la sculpture acoustique.",s2_title:"Une signature, plusieurs espaces.",s3_title:"Composer l'état, pas l'ambiance.",s4_title:"Le son à l'écoute du geste.",s5_title:"Une composition par soin.",s0_p1:"Tendez l'oreille. Ici, la musique se transforme à mesure que vous avancez : un aperçu de ce que nous composons pour votre futur espace, un son qui dialogue avec le lieu, l'instant et le geste.",s0_p2:"Chaque spa possède son climat sonore, qui agit sur le système nerveux avant même le premier soin. C'est souvent la première chose que ressent le client, et l'une des dernières qu'il emporte.",s0_p3:"Hôtels, instituts, thermes, retraites de longévité : nous composons cette signature, espace par espace, du seuil de l'accueil aux derniers instants de récupération. Une musique vivante, écrite par des compositeurs, guidée par les neurosciences.",s1_p1:"Sous tous les espaces du spa, une même trame épurée joue sans interruption. Une signature dépouillée, présente partout, qui ancre l'expérience et porte l'identité de la marque.",s1_p2:"Autour d'elle, chaque espace compose sa propre musique, en dialogue avec cette trame de fond. Réception, hammam, cabine, salon : chaque morceau épouse le même socle harmonique.",s1_p3:"Le client passe d'un espace à l'autre sans jamais percevoir de rupture. La composition change de texture, jamais d'identité. Une longue évolution, et non une succession de morceaux.",s2_p1:"Le client oublie l'essentiel de ce qu'il entend. Mais il se souvient de la façon dont un lieu sonnait.",s2_p2:"De l'accueil à la récupération, un spa est une succession de moments, chacun avec son rôle, sa propre intensité. Nous composons une signature sonore qui traverse tous les espaces, prend une forme propre à chacun, et demeure en mémoire longtemps après le dernier soin.",s2_p3:"Le client ne retient jamais un morceau. Il retient le lieu.",s3_p1:"Un soin n'a jamais une seule intention. Relâchement somatique, régulation parasympathique, ancrage attentionnel : ces états physiologiques sont aussi précis qu'un dosage.",s3_p2:"À chaque registre répond une trame sonore distincte.",s3_p3:"Nos compositions glissent d'un état à l'autre au fil du soin, sans transition perceptible.",s3_p4:"Le praticien guide le geste, la signature sonore guide le système nerveux. Les deux convergent sans jamais se concerter.",s4_p1:"Dans la cabine de soin, la musique ne doit pas être un décor. Elle doit suivre les mains au travail, en temps réel.",s4_p2:"Un capteur spatial perçoit la pièce : la position du praticien, le rythme du geste, le souffle du corps sur la table. La composition s'ajuste à ce qui se joue vraiment. La praticienne n'est plus accompagnée d'une playlist, mais portée par une composition qui l'écoute.",s4_p3:"Essayez maintenant. Activez votre caméra et bougez lentement devant elle. La musique s'ouvre avec votre mouvement, puis retombe vers la trame de fond dès que vous vous immobilisez. En cabine, la même logique passe par des capteurs spatiaux qui suivent le geste, non le visage. Une réponse calibrée, vivante, propre à chacun, sans intrusion.",s5_p1:"Derrière cette adaptation en temps réel, chaque soin a sa propre partition. Un soin d'une heure suit un arc : une arrivée, une prise de contact, une profondeur, un relâchement, un retour.",s5_p2:"La musique peut ignorer cet arc, ou l'épouser. Nous composons avec lui : cinq strates écrites pour cinq phases, qui entrent et s'effacent à mesure que le corps s'abandonne.",s5_p3:"La composition s'adapte au soin d'elle-même. Le capteur, lorsqu'il est présent, ajoute une réponse en temps réel au geste du praticien. Le corps se détend, et le système nerveux en garde la mémoire.",scroll_prompt:"Continuez de faire défiler lentement",isolation_on:"Écoute située active",isolation_off:"Bruit ambiant",phase_label:"phase du soin",phases_title:"Phases du soin",phase_1:"Bienvenue",phase_2:"Ouverture",phase_3:"Profondeur",phase_4:"Relâchement",phase_5:"Retour",zone_entree:"Accueil et transitions",zone_entree_sub:"Le seuil",zone_entree_body:"Réception, vestiaires, couloirs, tisanerie. La zone la plus bruyante du spa, là où l'agitation de la ville est encore présente. Notre composition masque les bruits parasites sans s'imposer, et prépare le système nerveux avant le premier soin.",zone_rayon:"Rituels de chaleur",zone_rayon_sub:"L'enveloppe",zone_rayon_body:"Hammam, sauna, douches sensorielles, parcours kneipp. Acoustique extrême, surfaces dures, vapeur. Notre composition épouse l'espace avec des basses chaudes et des textures organiques. L'objectif n'est pas la sédation, mais une détente éveillée, qui soutient la circulation et le souffle.",zone_equipe:"Cabines de soin",zone_equipe_sub:"Le geste",zone_equipe_body:"Modelage, drainage, soin du visage, soin énergétique. La main du praticien dialogue avec un système nerveux à vif. Nos trames sonores soutiennent le geste, sans hasard ni surprise. Le client s'abandonne, le praticien travaille en confiance.",zone_recuperation:"Espaces de récupération",zone_recuperation_sub:"L'empreinte",zone_recuperation_body:"Salles de détente, tisanerie, espaces calmes. L'étape la plus sous-estimée du parcours, et l'une des plus puissantes. Nos compositions prolongent l'état parasympathique et étendent le soin bien au-delà de la porte de la cabine. Le souvenir d'un spa est rarement visuel. Il est sonore.",neuro_relaxation:"Relâchement somatique",neuro_regulation:"Régulation parasympathique",neuro_focus:"Ancrage attentionnel",webcam_active:"Caméra active",webcam_authorize:"Autoriser la caméra",webcam_reading:"Lecture du geste",webcam_hint:"Autorisez la caméra, placez-vous face à elle en pleine lumière, puis bougez lentement. La musique s'ouvre avec le mouvement et revient au calme dès que vous vous immobilisez.",webcam_move_hint:"Bougez la main devant la caméra : la barre suit votre geste.",webcam_denied:"Caméra bloquée. Autorisez l'accès dans les réglages du navigateur, puis réessayez.",webcam_unavailable:"Caméra indisponible. Vérifiez qu'aucune autre application ne l'utilise, puis réessayez.",footer_about:"Qui sommes-nous",footer_legal:"Mentions légales",footer_contact:"Nous contacter",footer_email_placeholder:"Votre email",footer_message_placeholder:"Votre message",footer_send:"Envoyer",footer_copyright:"© 2026 Kikina Lab. Tous droits réservés.",footer_mailto_subject:"Contact depuis Kikiscroll Wellness",footer_mailto_body_prefix:"De : ",cta_title:"Quel est le son de votre espace ?",cta_body:"Vous avez un parfum. Vous avez une architecture. Vous avez un geste. Le son de votre spa ne devrait pas être laissé au hasard.",cta_invite:"Composons-le ensemble.",cta_email:"bianca@kikinastudio.com",legal_title:"Mentions Légales",legal_editor:"Éditeur du site :",legal_editor_value:"Kikina Lab / Kikina Studio",legal_address_label:"Siège social :",legal_address_value:"Paris, France",legal_contact_label:"Contact :",legal_hosting_label:"Hébergement :",legal_hosting_value:"Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723",legal_privacy:"Ce site utilise une détection de mouvement par caméra implémentée en JavaScript natif (différence d'images sur canvas). Aucune donnée d'image n'est enregistrée ou transmise à des serveurs tiers ; l'analyse est effectuée localement dans votre navigateur en temps réel.",legal_close:"Fermer"},en:{overlay_tagline:"At the crossroads of science, sound, and care.",overlay_cta:"Enter the sound experience",intro_eyebrow:"Composing presence.",intro_start:"Start the sound experience",intro_scroll:"Scroll slowly to explore",intro_line_1:"This is not a website.",intro_line_2:"It's a one-minute experience.",intro_line_3:"Scroll slowly. Sound on.",s0_title:"Sound, as a signature of care.",s1_title:"Sound that cancels the room.",s2_title:"One signature, many spaces.",s3_title:"Compose the state, not the ambience.",s4_title:"Sound that listens to the gesture.",s5_title:"A composition for every treatment.",s0_p1:"Listen closely. On this page, the music shifts with every section you scroll into, a quiet demonstration of how, in your future space, sound will live in dialogue with the room, the moment, the gesture.",s0_p2:"Every spa carries a sonic climate that shapes the nervous system before the first treatment. It is often the first sensation a guest receives, and one of the last impressions they carry away.",s0_p3:"Hotels, day spas, thermal baths, longevity retreats: we compose that signature, space by space, from the threshold of reception to the final moments of recovery. Living music, written by composers, guided by neuroscience.",s1_p1:"Our system listens to the room in real time and adapts the music to mask ambient noise.",s1_p2:"The result feels like noise-cancelling headphones, except no one is wearing any.",s1_p3:"Pure immersion, nothing in the way.",s2_p1:"Guests forget most of what they hear. But they remember how a place sounded.",s2_p2:"From reception to recovery, a spa is a sequence of moments, each with its own role and its own intensity. We compose a sonic signature that runs through every space, takes a different shape in each, and stays in memory long after the last treatment ends.",s2_p3:"The guest never recalls a track. They recall the place.",s3_p1:"A treatment has more than one intention. Somatic release, parasympathetic regulation, attentional grounding: these physiological states are as precise as a dosage.",s3_p2:"Each register has its own sonic fabric.",s3_p3:"Our compositions slide from one state to the next as the treatment unfolds, without perceptible transition.",s3_p4:"The practitioner guides the gesture, the sonic signature guides the nervous system. Both converge without coordination.",s4_p1:"In the treatment room, music should not be a backdrop. It should follow the hands at work, in real time.",s4_p2:"A spatial sensor reads the room: the position of the practitioner, the rhythm of the gesture, the breath of the body on the table. The composition adjusts to what is actually unfolding. The practitioner is no longer accompanied by a playlist, but partnered by a composition that listens to her.",s4_p3:"Try it now. Turn on your camera and move slowly in front of it. The music opens up with your movement and settles back to the underlying layer the moment you hold still. In the treatment room, the same logic runs through spatial sensors that follow the gesture, not the face. A calibrated response, alive, individual, without intrusion.",s5_p1:"Behind this real-time adaptation, every treatment has its own original score. A one-hour treatment has an arc: an arrival, a first contact, a depth, a release, a return.",s5_p2:"The music can ignore that arc, or follow it. We compose alongside it: five strata written for five phases, entering and stepping back as the body settles.",s5_p3:"The composition adapts to the treatment by itself. The sensor, when present, adds a live response to the practitioner's gesture. The body softens. The nervous system remembers the precision.",scroll_prompt:"Keep scrolling slowly",isolation_on:"Situated listening active",isolation_off:"Ambient noise",phase_label:"treatment phase",phases_title:"Treatment phases",phase_1:"Welcome",phase_2:"Opening",phase_3:"Depth",phase_4:"Release",phase_5:"Return",zone_entree:"Receptions and transitions",zone_entree_sub:"The threshold",zone_entree_body:"Reception, changing rooms, corridors, tea lounge. The loudest zone of the spa, where the urban state still lingers. Our composition masks the parasitic sounds without imposing itself, and prepares the nervous system before the first treatment.",zone_rayon:"Heat rituals",zone_rayon_sub:"The envelope",zone_rayon_body:"Hammam, sauna, sensory showers, Kneipp path. Extreme acoustics, hard surfaces, steam. Our composition meets the volume with warm bass and organic textures. The aim is not sedation but alert relaxation, supporting circulation and breath.",zone_equipe:"Treatment rooms",zone_equipe_sub:"The gesture",zone_equipe_body:"Massage, drainage, facial, energy work. The practitioner's hand dialogues with a raw nervous system. Our sonic textures support the gesture without randomness or surprise. The guest surrenders, the practitioner works in confidence.",zone_recuperation:"Recovery spaces",zone_recuperation_sub:"The imprint",zone_recuperation_body:"Relaxation lounges, tisanerie, quiet rooms. The most underestimated stage of the journey, and one of the most powerful. Our compositions extend the parasympathetic state and carry the treatment well beyond the cabin door. The memory of a spa is rarely visual. It is sonic.",neuro_relaxation:"Somatic release",neuro_regulation:"Parasympathetic regulation",neuro_focus:"Attentional grounding",webcam_active:"Motion sensor active",webcam_authorize:"Allow motion sensor",webcam_reading:"Reading the gesture",webcam_hint:"Motion sensor only. No recording.",webcam_move_hint:"Move your hand in front of the camera — the bar follows your gesture.",webcam_denied:"Camera blocked. Allow access in your browser settings, then try again.",webcam_unavailable:"Camera unavailable. Make sure no other app is using it, then try again.",footer_about:"About us",footer_legal:"Legal notice",footer_contact:"Contact us",footer_email_placeholder:"Your email",footer_message_placeholder:"Your message",footer_send:"Send",footer_copyright:"© 2026 Kikina Lab. All rights reserved.",footer_mailto_subject:"Contact from Kikiscroll Wellness",footer_mailto_body_prefix:"From: ",cta_title:"What does your space sound like?",cta_body:"You have a fragrance. You have an architecture. You have a gesture. The sound of your spa should not be left to chance.",cta_invite:"Let's compose it together.",cta_email:"bianca@kikinastudio.com",legal_title:"Legal Notice",legal_editor:"Site publisher:",legal_editor_value:"Kikina Lab / Kikina Studio",legal_address_label:"Registered office:",legal_address_value:"Paris, France",legal_contact_label:"Contact:",legal_hosting_label:"Hosting:",legal_hosting_value:"Vercel Inc., 440 N Barranca Ave #4133, Covina, CA 91723",legal_privacy:"This site uses webcam motion detection implemented in pure JavaScript (frame-difference on a canvas). No image data is recorded or transmitted to third-party servers; analysis is performed locally in your browser in real time.",legal_close:"Close"}},l={retail:i,wellness:r},a=s.createContext("fr");function p({lang:e,children:t}){return o.jsx(a.Provider,{value:e,children:t})}function m(){const e=s.useContext(a),t=n();return{t:l[t][e],lang:e,mode:t}}export{p as LanguageProvider,m as useTranslation};
